// Node A: Extract query and build LLM classification prompt
const body = $input.first().json.body || $input.first().json;
const query = body.query || body.chatInput || body.task_query || '';
const tenant_id = body.tenant_id || body.sector || 'benchmark';

const prompt = `You are a query router for a sector-expert AI system with 3 specialized pipelines:

1. STANDARD — General knowledge questions about a sector (regulations, norms, procedures, definitions, explanations). Use for: "What is...", "Explain...", "What are the norms for...", "How does X work?"

2. GRAPH — Entity relationship questions (connections between companies, people, organizations, laws, standards). Use for: "What is the relationship between X and Y?", "Which companies supply X?", "What laws apply to X?", "List all entities connected to X"

3. QUANTITATIVE — Numerical/financial data questions requiring SQL queries on structured data (revenue, margins, ratios, comparisons, counts, totals). Use for: "What is the revenue of X?", "Compare margins of X and Y", "How many employees at X?", "What is the debt ratio?"

MULTI-PIPELINE: If the question needs MULTIPLE pipelines, list them ALL. Example: "Give me a full analysis of Microsoft including financials and competitors" → ["standard", "quantitative", "graph"]

Question: "${query.replace(/"/g, '\\"')}"

Respond in EXACTLY this JSON format, nothing else:
{"intents": ["standard"], "confidence": 0.95, "reasoning": "brief explanation"}

If multiple pipelines needed:
{"intents": ["standard", "quantitative"], "confidence": 0.85, "reasoning": "needs both knowledge and numbers"}`;

return [{ json: { query, tenant_id, prompt, top_k: 10, include_sources: true } }];

