// Node C: Parse LLM classification response with regex fallback
const raw = $input.first().json;
let classification;

try {
  const content = raw.choices?.[0]?.message?.content || '';
  // Try parsing JSON directly
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    classification = JSON.parse(jsonMatch[0]);
  }
} catch(e) {
  classification = null;
}

// Validate intents are valid pipeline names
const VALID_INTENTS = ['standard', 'graph', 'quantitative'];
if (classification && Array.isArray(classification.intents)) {
  classification.intents = classification.intents.filter(i => VALID_INTENTS.includes(i));
  if (classification.intents.length === 0) classification = null;
}

// Fallback to regex if LLM fails or returns invalid
if (!classification || !classification.intents || !Array.isArray(classification.intents)) {
  const q = ($node['Prepare Classification'].json.query || '').toLowerCase();
  let intent = 'standard';
  if (/chiffre|revenue|bilan|profit|perte|total|montant|combien|marge|ratio|\d+\s*(euros?|%|millions?|milliards?)/.test(q)) {
    intent = 'quantitative';
  } else if (/relation|lien|connect|entre.*et|qui.*avec|réseau|graphe|fournisseur|client|partenaire/.test(q)) {
    intent = 'graph';
  }
  classification = { intents: [intent], confidence: 0.5, reasoning: 'regex fallback (LLM unavailable)' };
}

const initData = $node['Prepare Classification'].json;
const primaryIntent = classification.intents[0];
const multiPipeline = classification.intents.length > 1;

return [{ json: {
  query: initData.query,
  tenant_id: initData.tenant_id,
  top_k: initData.top_k,
  include_sources: initData.include_sources,
  intent: primaryIntent,
  all_intents: classification.intents,
  multi_pipeline: multiPipeline,
  confidence: classification.confidence,
  reasoning: classification.reasoning
}}];

// Fan out: call ALL pipelines listed in all_intents in parallel
const data = $input.first().json;
const intents = data.all_intents || ['standard'];

// Build pipeline URL map
const PIPELINE_URLS = {
  standard: 'https://lbjlincoln-nomos-rag-engine-3.hf.space/webhook/rag-multi-index-v3',
  graph: 'https://lbjlincoln-nomos-rag-engine.hf.space/webhook/ff622742-6d71-4e91-af71-b5c666088717',
  quantitative: 'https://lbjlincoln-nomos-rag-engine-9.hf.space/webhook/3e0f8010-39e0-4bca-9d19-35e5094391a9'
};

// Call all pipelines in parallel using Promise.all
const results = await Promise.all(intents.map(async (intent) => {
  const url = PIPELINE_URLS[intent];
  if (!url) return { intent, error: 'unknown pipeline', response: '', sources: [] };

  const payload = {
    query: data.query,
    tenant_id: data.tenant_id,
    top_k: data.top_k || 10,
    include_sources: true
  };

  try {
    const resp = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(90000)
    });
    let result = await resp.json();
    // Handle array responses
    if (Array.isArray(result)) result = result[0] || {};
    return {
      intent,
      response: result.response || result.answer || result.final_response || result.result || result.interpretation || '',
      sources: result.sources || [],
      engine: result.engine || intent
    };
  } catch(e) {
    return { intent, error: e.message, response: '', sources: [] };
  }
}));

// Merge all responses
const mergedParts = [];
const allSources = [];
const pipelines = [];

for (const r of results) {
  pipelines.push(r.intent);
  if (r.response) {
    mergedParts.push(`[${r.intent.toUpperCase()}]\n${r.response}`);
  }
  if (Array.isArray(r.sources)) {
    allSources.push(...r.sources);
  }
}

// Deduplicate sources by title or content
const seenTitles = new Set();
const uniqueSources = allSources.filter(s => {
  const key = s.title || s.source || JSON.stringify(s);
  if (seenTitles.has(key)) return false;
  seenTitles.add(key);
  return true;
});

return [{ json: {
  response: mergedParts.join('\n\n---\n\n') || 'No response from pipelines',
  sources: uniqueSources.slice(0, 15),
  pipeline_used: pipelines.join('+'),
  multi_pipeline: true,
  pipelines_called: pipelines,
  classification: {
    intent: data.intent,
    all_intents: data.all_intents,
    confidence: data.confidence,
    reasoning: data.reasoning
  },
  timestamp: new Date().toISOString()
}}];

// Format response from single-pipeline call with classification metadata
const raw = $input.first().json;
let data = raw;
if (Array.isArray(data)) data = data[0] || {};
if (data.body) {
  try { data = typeof data.body === 'string' ? JSON.parse(data.body) : data.body; } catch(e) {}
  if (Array.isArray(data)) data = data[0] || {};
}

const response = data.response || data.answer || data.final_response || data.result || data.interpretation || '';
const sources = data.sources || [];

// Get classification metadata from Parse Classification node
let classificationMeta = {};
try {
  const parseNode = $node['Parse Classification'].json;
  classificationMeta = {
    intent: parseNode.intent,
    all_intents: parseNode.all_intents,
    confidence: parseNode.confidence,
    reasoning: parseNode.reasoning
  };
} catch(e) {
  classificationMeta = { intent: 'unknown', all_intents: ['unknown'], confidence: 0, reasoning: 'metadata unavailable' };
}

return [{
  json: {
    response: response || 'No response from pipeline',
    sources: Array.isArray(sources) ? sources.slice(0, 10) : [],
    pipeline_used: data.engine || classificationMeta.intent || 'orchestrator',
    multi_pipeline: false,
    classification: classificationMeta,
    timestamp: new Date().toISOString()
  }
}];

// Pass through multi-pipeline merged result (already formatted)
const data = $input.first().json;
return [{ json: data }];

// Final merge: accept output from either single or multi pipeline path
const data = $input.first().json;
return [{ json: data }];
